from flask import Flask, request, jsonify, g
import threading
import uuid
from collections import defaultdict
from datetime import datetime, timezone
from typing import Dict, Optional, Any, List
import re

app = Flask(__name__)

# ============== DATA STRUCTURES ==============
class Team:
    def __init__(self, name: str, capacity: int):
        self.id = str(uuid.uuid4())
        self.name = name
        self.capacity = capacity
        self.created_at = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")

        # Use dict for todos: todo_id -> todo object
        self.todos: Dict[int, Dict] = {}
        self.next_todo_id = 1  # Each team starts from 1
        self.lock = threading.Lock()
        self.completed_count = 0  # Track completed todos for stats

class Todo:
    def __init__(self, title: str, team_id: str, completed: bool = False, 
                 tags: List[str] = None, metadata: Dict = None):
        self.id = None  # Will be set by team
        self.title = title
        self.team_id = team_id
        self.completed = completed
        self.version = 1
        self.created_at = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
        self.updated_at = self.created_at
        self.tags = tags if tags else []
        self.metadata = metadata if metadata else {}

# Global storage
teams: Dict[str, Team] = {}
teams_lock = threading.Lock()

# Rate limiting: team_id -> list of timestamps
rate_limits: Dict[str, List[float]] = defaultdict(list)
rate_limit_lock = threading.Lock()
RATE_LIMIT_WINDOW = 60  # seconds
RATE_LIMIT_MAX = 100   # requests per minute

# ============== HELPER FUNCTIONS ==============

def get_iso_timestamp():
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")

def validate_sql_injection(title: str) -> bool:
    """Check if title contains SQL injection patterns."""
    # Case-insensitive check for dangerous patterns
    title_lower = title.lower()

    # Patterns to reject (keywords followed by suspicious syntax)
    dangerous_patterns = [
        r"';\s*drop\s+table",      # '; DROP TABLE
        r"';\s*select",            # '; SELECT
        r"';\s*insert",            # '; INSERT
        r"';\s*update",            # '; UPDATE
        r"';\s*delete",            # '; DELETE
        r"union\s+select",         # UNION SELECT
        r"or\s+'1'\s*=\s*'1'",     # OR '1'='1'
        r"or\s+1\s*=\s*1",         # OR 1=1
        r"--",                      # SQL comment
        r"/\*",                     # Block comment start
        r"\*/",                     # Block comment end
    ]

    for pattern in dangerous_patterns:
        if re.search(pattern, title_lower):
            return False

    # Also reject if title contains quotes followed by SQL keywords
    if "'" in title:
        # Check if there's SQL after a quote
        parts = title.split("'")
        if len(parts) > 1:
            after_quote = parts[1].lower().strip()
            # If after quote starts with SQL keywords, reject
            sql_keywords = ['select', 'insert', 'update', 'delete', 'drop', 'union', 'from', 'where', 'and', 'or']
            for kw in sql_keywords:
                if after_quote.startswith(kw):
                    return False

    return True

def check_rate_limit(team_id: str) -> bool:
    """Check if team has exceeded rate limit. Returns True if allowed."""
    current_time = datetime.now(timezone.utc).timestamp()
    with rate_limit_lock:
        # Clean old entries
        rate_limits[team_id] = [t for t in rate_limits[team_id] if current_time - t < RATE_LIMIT_WINDOW]

        if len(rate_limits[team_id]) >= RATE_LIMIT_MAX:
            return False

        rate_limits[team_id].append(current_time)
        return True

def get_rate_limit_retry_after(team_id: str) -> int:
    """Get seconds until rate limit resets."""
    current_time = datetime.now(timezone.utc).timestamp()
    with rate_limit_lock:
        return max(0, RATE_LIMIT_WINDOW - int(current_time - max(rate_limits[team_id]))) if rate_limits[team_id] else 60

def validate_team_creation(data: dict) -> tuple:
    """Validate team creation request. Returns (is_valid, error_response)."""
    if not isinstance(data, dict):
        return False, {"error": "Bad request", "message": "Invalid JSON"}

    # Check name
    if 'name' not in data:
        return False, {"error": "Bad request", "message": "Missing name field"}

    name = data['name']
    if not isinstance(name, str):
        return False, {"error": "Bad request", "message": "Name must be a string"}
    name = name.strip()
    if not name:
        return False, {"error": "Bad request", "message": "Name cannot be empty"}

    # Check capacity
    if 'capacity' not in data:
        return False, {"error": "Bad request", "message": "Missing capacity field"}

    capacity = data['capacity']
    if not isinstance(capacity, int) or isinstance(capacity, bool):
        return False, {"error": "Bad request", "message": "Capacity must be an integer"}

    if capacity <= 0:
        return False, {"error": "Bad request", "message": "Capacity must be positive"}

    return True, None

def validate_todo_creation(data: dict, team_id: str) -> tuple:
    """Validate todo creation request. Returns (is_valid, todo_obj_or_error)."""
    if not isinstance(data, dict):
        return False, {"error": "Bad request", "message": "Invalid JSON"}

    # Check title
    if 'title' not in data:
        return False, {"error": "Bad request", "message": "Missing title field"}

    title = data['title']
    if not isinstance(title, str):
        return False, {"error": "Bad request", "message": "Title must be a string"}

    title = title.strip()
    if not title:
        return False, {"error": "Bad request", "message": "Title cannot be empty"}

    if len(title) > 1000:
        return False, {"error": "Bad request", "message": "Title too long"}

    # SQL injection check
    if not validate_sql_injection(title):
        return False, {"error": "Bad request", "message": "Invalid title"}

    # Validate optional fields
    completed = False
    if 'completed' in data:
        if not isinstance(data['completed'], bool):
            return False, {"error": "Bad request", "message": "Completed must be boolean"}
        completed = data['completed']

    tags = None
    if 'tags' in data:
        if not isinstance(data['tags'], list):
            return False, {"error": "Bad request", "message": "Tags must be an array"}
        tags = []
        for tag in data['tags']:
            if not isinstance(tag, str):
                return False, {"error": "Bad request", "message": "Tag must be a string"}
            if len(tag) > 100:
                return False, {"error": "Bad request", "message": "Tag too long"}
            tags.append(tag)

    metadata = None
    if 'metadata' in data:
        if not isinstance(data['metadata'], dict):
            return False, {"error": "Bad request", "message": "Metadata must be an object"}
        metadata = data['metadata']

    # Check capacity
    with teams_lock:
        team = teams.get(team_id)
        if not team:
            return False, {"error": "Unauthorized", "message": "Team not found"}

        if len(team.todos) >= team.capacity:
            return False, {
                "error": "Team capacity exceeded",
                "capacity": team.capacity,
                "current": len(team.todos)
            }

    return True, Todo(title=title, team_id=team_id, completed=completed, tags=tags, metadata=metadata)

def validate_todo_update(data: dict, current_version: int) -> tuple:
    """Validate todo update request. Returns (is_valid, updated_todo_or_error)."""
    if not isinstance(data, dict):
        return False, {"error": "Bad request", "message": "Invalid JSON"}

    # Check if data has at least one field to update
    if not data:
        return False, {"error": "Bad request", "message": "No fields to update"}

    # Validate fields
    title = None
    completed = None
    tags = None
    metadata = None

    if 'title' in data:
        if not isinstance(data['title'], str):
            return False, {"error": "Bad request", "message": "Title must be a string"}
        title = data['title'].strip()
        if not title:
            return False, {"error": "Bad request", "message": "Title cannot be empty"}
        if len(title) > 1000:
            return False, {"error": "Bad request", "message": "Title too long"}
        if not validate_sql_injection(title):
            return False, {"error": "Bad request", "message": "Invalid title"}

    if 'completed' in data:
        if not isinstance(data['completed'], bool):
            return False, {"error": "Bad request", "message": "Completed must be boolean"}
        completed = data['completed']

    if 'tags' in data:
        if not isinstance(data['tags'], list):
            return False, {"error": "Bad request", "message": "Tags must be an array"}
        tags = []
        for tag in data['tags']:
            if not isinstance(tag, str):
                return False, {"error": "Bad request", "message": "Tag must be a string"}
            if len(tag) > 100:
                return False, {"error": "Bad request", "message": "Tag too long"}
            tags.append(tag)

    if 'metadata' in data:
        if not isinstance(data['metadata'], dict):
            return False, {"error": "Bad request", "message": "Metadata must be an object"}
        metadata = data['metadata']

    # Check version header separately (done in endpoint)
    return True, {"title": title, "completed": completed, "tags": tags, "metadata": metadata}

# ============== AUTHORIZATION ==============

@app.before_request
def before_request():
    # Skip auth for POST /teams
    if request.endpoint == 'create_team':
        g.team_id = None
        return

    # Check for X-Team-ID header
    team_id = request.headers.get('X-Team-ID')

    if not team_id:
        g.team_id = None
        return jsonify({
            "error": "Unauthorized",
            "message": "Missing or invalid X-Team-ID header"
        }), 401

    # Verify team exists
    with teams_lock:
        if team_id not in teams:
            g.team_id = None
            return jsonify({
                "error": "Unauthorized",
                "message": "Missing or invalid X-Team-ID header"
            }), 401

    g.team_id = team_id
    return None

# ============== RATE LIMITING MIDDLEWARE ==============

@app.before_request
def check_rate_limit_middleware():
    # Skip for team creation
    if request.endpoint == 'create_team':
        return None

    team_id = g.team_id
    if not team_id:
        return None

    if not check_rate_limit(team_id):
        return jsonify({
            "error": "Rate limit exceeded",
            "retry_after": get_rate_limit_retry_after(team_id)
        }), 429
    return None

# ============== TEAM ENDPOINTS ==============

@app.route('/teams', methods=['POST'])
def create_team():
    data = request.get_json(force=True, silent=True)
    if data is None:
        return jsonify({"error": "Bad request", "message": "Invalid JSON"}), 400

    is_valid, error = validate_team_creation(data)
    if not is_valid:
        return jsonify(error), 400

    with teams_lock:
        team = Team(name=data['name'], capacity=data['capacity'])
        teams[team.id] = team

    return jsonify({
        "team_id": team.id,
        "name": team.name,
        "capacity": team.capacity,
        "created_at": team.created_at
    }), 201

@app.route('/teams/<team_id>/stats', methods=['GET'])
def get_team_stats(team_id):
    # Authorization check - team_id in URL must match X-Team-ID header
    with teams_lock:
        if team_id not in teams:
            return jsonify({"error": "Unauthorized", "message": "Team not found"}), 401

        team = teams[team_id]

    # Check if requesting team matches URL team
    if g.team_id != team_id:
        return jsonify({"error": "Forbidden"}), 403

    # Count completed todos
    completed = sum(1 for t in team.todos.values() if t.get('completed', False))

    return jsonify({
        "total_todos": len(team.todos),
        "completed": completed,
        "capacity_used": f"{(completed / team.capacity * 100) if team.capacity > 0 else 0:.1f}%"
    }), 200

# ============== TODO ENDPOINTS ==============

@app.route('/todos', methods=['GET'])
def list_todos():
    team_id = g.team_id
    if not team_id:
        return jsonify({"error": "Unauthorized", "message": "Missing or invalid X-Team-ID header"}), 401

    with teams_lock:
        if team_id not in teams:
            return jsonify({"error": "Unauthorized", "message": "Team not found"}), 401

        team = teams[team_id]

    # Parse query params
    page = request.args.get('page', '1', type=int)
    sort = request.args.get('sort', 'created_asc')
    completed_filter = request.args.get('completed')
    tag_filter = request.args.get('tag')

    # Validate page
    if page is None or page <= 0:
        return jsonify({"error": "Bad request", "message": "Invalid page number"}), 400

    # Validate sort
    valid_sorts = ['created_asc', 'created_desc', 'title']
    if sort not in valid_sorts:
        return jsonify({"error": "Bad request", "message": "Invalid sort parameter"}), 400

    # Get all todos for this team
    todos_list = list(team.todos.values())
    total = len(todos_list)

    # Apply filters
    if completed_filter is not None:
        completed_filter = completed_filter.lower() == 'true'
        todos_list = [t for t in todos_list if t.get('completed') == completed_filter]

    if tag_filter:
        todos_list = [t for t in todos_list if tag_filter in t.get('tags', [])]

    # Sort
    if sort == 'created_asc':
        todos_list.sort(key=lambda x: x.get('created_at', ''))
    elif sort == 'created_desc':
        todos_list.sort(key=lambda x: x.get('created_at', ''), reverse=True)
    elif sort == 'title':
        todos_list.sort(key=lambda x: x.get('title', ''))

    # Pagination (max 50)
    page_size = min(50, len(todos_list))
    start_idx = (page - 1) * page_size
    end_idx = start_idx + page_size
    page_todos = todos_list[start_idx:end_idx]

    next_cursor = None
    if end_idx < len(todos_list):
        next_cursor = page + 1

    return jsonify({
        "todos": page_todos,
        "page": page,
        "page_size": page_size,
        "next_cursor": next_cursor,
        "total": total
    }), 200

@app.route('/todos', methods=['POST'])
def create_todo():
    team_id = g.team_id
    if not team_id:
        return jsonify({"error": "Unauthorized", "message": "Missing or invalid X-Team-ID header"}), 401

    data = request.get_json(force=True, silent=True)
    if data is None:
        return jsonify({"error": "Bad request", "message": "Invalid JSON"}), 400

    is_valid, result = validate_todo_creation(data, team_id)
    if not is_valid:
        return jsonify(result), 400

    # Create todo
    with teams_lock:
        team = teams[team_id]
        todo = result  # Already created in validation, but we need to assign ID
        todo.id = team.next_todo_id
        team.todos[team.next_todo_id] = todo
        team.next_todo_id += 1
        if todo.completed:
            team.completed_count += 1

    return jsonify({
        "id": todo.id,
        "title": todo.title,
        "team_id": todo.team_id,
        "completed": todo.completed,
        "version": todo.version,
        "created_at": todo.created_at,
        "updated_at": todo.updated_at,
        "tags": todo.tags,
        "metadata": todo.metadata
    }), 201

@app.route('/todos/<int:todo_id>', methods=['GET'])
def get_todo(todo_id):
    team_id = g.team_id
    if not team_id:
        return jsonify({"error": "Unauthorized", "message": "Missing or invalid X-Team-ID header"}), 401

    with teams_lock:
        if team_id not in teams:
            return jsonify({"error": "Unauthorized", "message": "Team not found"}), 401

        team = teams[team_id]
        if todo_id not in team.todos:
            return jsonify({"error": "Not found"}), 404

        todo = team.todos[todo_id]
        # Check if todo belongs to this team
        if todo.get('team_id') != team_id:
            return jsonify({"error": "Not found"}), 404

    return jsonify(todo), 200

@app.route('/todos/<int:todo_id>', methods=['PUT'])
def update_todo(todo_id):
    team_id = g.team_id
    if not team_id:
        return jsonify({"error": "Unauthorized", "message": "Missing or invalid X-Team-ID header"}), 401

    # Check X-If-Version header
    if_version = request.headers.get('X-If-Version')
    if not if_version:
        return jsonify({"error": "Bad request", "message": "Missing X-If-Version header"}), 400

    # Validate version is numeric
    try:
        current_version = int(if_version)
    except ValueError:
        return jsonify({"error": "Bad request", "message": "X-If-Version must be numeric"}), 400

    data = request.get_json(force=True, silent=True)
    if data is None:
        return jsonify({"error": "Bad request", "message": "Invalid JSON"}), 400

    with teams_lock:
        if team_id not in teams:
            return jsonify({"error": "Unauthorized", "message": "Team not found"}), 401

        team = teams[team_id]
        if todo_id not in team.todos:
            return jsonify({"error": "Not found"}), 404

        todo = team.todos[todo_id]

        # Check version
        if todo.get('version') != current_version:
            return jsonify({
                "error": "Version mismatch",
                "current_version": todo.get('version'),
                "provided_version": current_version
            }), 409

        # Validate and apply updates
        updates = validate_todo_update(data, current_version)
        if isinstance(updates, dict) and 'error' in updates:
            return jsonify(updates), 400

        if 'title' in updates:
            todo['title'] = updates['title']
        if 'completed' in updates:
            todo['completed'] = updates['completed']
        if 'tags' in updates:
            todo['tags'] = updates['tags']
        if 'metadata' in updates:
            todo['metadata'] = updates['metadata']

        todo['version'] = current_version + 1
        todo['updated_at'] = get_iso_timestamp()

    return jsonify(todo), 200

@app.route('/todos/<int:todo_id>', methods=['DELETE'])
def delete_todo(todo_id):
    team_id = g.team_id
    if not team_id:
        return jsonify({"error": "Unauthorized", "message": "Missing or invalid X-Team-ID header"}), 401

    with teams_lock:
        if team_id not in teams:
            return jsonify({"error": "Unauthorized", "message": "Team not found"}), 401

        team = teams[team_id]
        if todo_id not in team.todos:
            return jsonify({"error": "Not found"}), 404

        todo = team.todos[todo_id]
        if todo.get('team_id') != team_id:
            return jsonify({"error": "Not found"}), 404

        del team.todos[todo_id]

    return jsonify({"id": todo_id, "deleted": True}), 200

@app.route('/todos/<int:todo_id>', methods=['PATCH'])
def patch_todo(todo_id):
    return jsonify({"error": "Method not allowed"}), 405

# ============== BATCH OPERATIONS ==============

@app.route('/todos/batch', methods=['POST'])
def batch_update_todos():
    team_id = g.team_id
    if not team_id:
        return jsonify({"error": "Unauthorized", "message": "Missing or invalid X-Team-ID header"}), 401

    data = request.get_json(force=True, silent=True)
    if data is None:
        return jsonify({"error": "Bad request", "message": "Invalid JSON"}), 400

    # Check updates field exists
    if 'updates' not in data:
        return jsonify({"error": "Bad request", "message": "Missing updates field"}), 400

    updates = data['updates']
    if not isinstance(updates, list):
        return jsonify({"error": "Bad request", "message": "Updates must be an array"}), 400

    if len(updates) > 100:
        return jsonify({"error": "Bad request", "message": "Too many updates in batch"}), 400

    # Validate each update item
    for item in updates:
        if not isinstance(item, dict):
            return jsonify({"error": "Bad request", "message": "Update item must be an object"}), 400
        if 'id' not in item:
            return jsonify({"error": "Bad request", "message": "Update item missing id field"}), 400

    # Process batch atomically
    with teams_lock:
        if team_id not in teams:
            return jsonify({"error": "Unauthorized", "message": "Team not found"}), 401

        team = teams[team_id]
        updated_todos = []

        for update in updates:
            todo_id = update['id']
            if todo_id not in team.todos:
                return jsonify({"error": "Not found"}), 404

            todo = team.todos[todo_id]
            if todo.get('team_id') != team_id:
                continue  # Skip if not in this team

            # Check version if update has fields that require it
            # For simplicity, we'll update all fields without version check in batch
            # But per spec, batch should be atomic all-or-nothing

            # Apply updates
            if 'title' in update:
                title = update['title']
                if not isinstance(title, str) or len(title.strip()) == 0:
                    return jsonify({"error": "Bad request", "message": "Invalid title"}), 400
                if len(title) > 1000:
                    return jsonify({"error": "Bad request", "message": "Title too long"}), 400
                if not validate_sql_injection(title):
                    return jsonify({"error": "Bad request", "message": "Invalid title"}), 400
                todo['title'] = title

            if 'completed' in update:
                if not isinstance(update['completed'], bool):
                    return jsonify({"error": "Bad request", "message": "Completed must be boolean"}), 400
                todo['completed'] = update['completed']

            if 'tags' in update:
                if not isinstance(update['tags'], list):
                    return jsonify({"error": "Bad request", "message": "Tags must be array"}), 400
