def validate_sql_injection(title: str) -> bool:
    """Check if title contains SQL injection patterns. Returns True if safe."""
    title_lower = title.lower()

    # Dangerous patterns - these should be rejected
    dangerous_patterns = [
        r"';\s*drop\s",          # '; DROP
        r"';\s*select\s",        # '; SELECT  
        r"';\s*insert\s",        # '; INSERT
        r"';\s*update\s",        # '; UPDATE
        r"';\s*delete\s",        # '; DELETE
        r"';\s*union\s",         # '; UNION
        r"union\s+select",       # UNION SELECT
        r"'\s*or\s+'1'\s*=\s*'1'",  # ' OR '1'='1'
        r"'\s*or\s+1\s*=\s*1",   # ' OR 1=1
        r"--",                   # SQL comment
        r"/\*",                  # Block comment
    ]

    for pattern in dangerous_patterns:
        if re.search(pattern, title_lower):
            return False

