    if "'" in title:
        quote_pos = title.find("'")
        after_quote = title[quote_pos+1:].strip().lower()
        sql_keywords = ['select', 'insert', 'update', 'delete', 'drop', 'union', 'from', 'where']
        for kw in sql_keywords:
            if after_quote.startswith(kw):
                return False

    return True

