    """Check rate limit. Returns (allowed, retry_after_seconds)."""
    current_time = datetime.now(timezone.utc).timestamp()
    with rate_limit_lock:
        # Clean old entries
        cutoff = current_time - RATE_LIMIT_WINDOW
        rate_limits[team_id] = [t for t in rate_limits[team_id] if t > cutoff]

        if len(rate_limits[team_id]) >= RATE_LIMIT_MAX:
