        r"';\s*select\s",
        r"';\s*insert\s",
        r"';\s*update\s",
        r"';\s*delete\s",
        r"';\s*union\s",
        r"union\s+select",
        r"--",
        r"/\*",
        r"'\s+or\s+'1'\s*=\s*'1'",
        r"'\s+or\s+1\s*=\s*1",
    ]

    for pattern in dangerous_patterns:
        if re.search(pattern, title_lower):
